#!/bin/bash
# /grids — Quick grid status check
SSH="ssh -i ~/.ssh/martin_vm.key -o StrictHostKeyChecking=no -o ConnectTimeout=10 ubuntu@141.253.108.141"
$SSH "for g in \$(curl -s http://localhost:8081/api/grid/active 2>/dev/null | python3 -c 'import sys,json; [print(x) for x in json.load(sys.stdin)]'); do S=\$(curl -s http://localhost:8081/api/grid/status/\$g); echo \"\$g RT=\$(echo \$S | python3 -c 'import sys,json; print(json.load(sys.stdin)[\"completedRoundTrips\"])') Fills=\$(echo \$S | python3 -c 'import sys,json; print(len(json.load(sys.stdin)[\"fills\"]))') Profit=\$(echo \$S | python3 -c 'import sys,json; print(json.load(sys.stdin)[\"totalProfit\"])') Mode=\$(echo \$S | python3 -c 'import sys,json; print(json.load(sys.stdin).get(\"gridMode\",\"?\"))')\"; done && curl -s http://localhost:8081/api/bot/balance | python3 -c 'import sys,json; f=json.load(sys.stdin)[\"accounts\"][\"flex\"]; print(\"PV:\",round(f[\"portfolioValue\"],2),\"Avail:\",round(f[\"availableMargin\"],2),\"PnL:\",round(f[\"pnl\"],4))'"
